select 'gincana-reciclaveis', 'II Gincana de entrega voluntária de recicláveis', 'Extensão · Educação ambiental', 'Educação ambiental e coleta de recicláveis para apoiar cooperativas e a conscientização da comunidade escolar.', 'O projeto aborda a gestão de resíduos recicláveis, incluindo plásticos, metais, papel e papelão, com destinação a cooperativa coletora. A proposta promove a conscientização ambiental e o desenvolvimento sustentável, em alinhamento com a Agenda 2030. Erick participa como integrante.

Período: 2023.
Natureza: Extensão.
Situação no Lattes: Concluído.
Participação: integrante.
Coordenação: Daniela Tissuya Silva Toda.', array['Reciclagem', 'Educação ambiental', 'Sustentabilidade']::text[], null, null, true
where not exists (select 1 from public.projects where slug = 'gincana-reciclaveis' or lower(btrim(title)) = lower(btrim('II Gincana de entrega voluntária de recicláveis')))
on conflict (slug) do nothing;

